}

export interface ScanReport {
  examined: number;
  created: number;
  already: number;
  unmatched: number;
  ignored: number;
  items: ScanItem[];
}

export function configFromEnv(): MailboxConfig | null {
  const host = process.env.MAIL_HOST;
  const user = process.env.MAIL_USER;
