bun -e '
import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { parseDispatchEmail } from "./src/providers/email.ts";

const oldTrack = /(?:tracking(?:\s+id|\s+number)?|gu[ií]a|c[oó]digo de seguimiento|rastreo)\s*[:#]?\s*([A-Z0-9-]{8,40})/i;
const newTrack = /(?:tracking(?:\s+id|\s+number)?|gu[ií]a|c[oó]digo de seguimiento|n[uú]mero de seguimiento|rastreo)\s*[:#]?\s*([A-Z0-9-]{8,40})/i;
const oldCar = /(?:carrier|transportadora|enviado con|shipped with)\s*[:#]?\s*([A-Za-z][A-Za-z0-9 .'"'"'-]{1,40})/i;
const newCar = /(?:carrier|transportadora|transportista|enviado con|shipped with)\s*[:#]?\s*([A-Za-z][A-Za-z0-9 .'"'"'-]{1,40})/i;

function bodyOf(raw) {
  const split = raw.split(/\r?\n\r?\n/);
  return split.length > 1 ? split.slice(1).join("\n") : raw;
}

const dirs = ["fixtures/correos", "harness/casos", "harness/regresion"];
for (const dir of dirs) {
  for (const f of readdirSync(dir).filter(n => n.endsWith(".txt")).sort()) {
    const raw = readFileSync(join(dir, f), "utf8");
    const text = bodyOf(raw);
    const parsed = parseDispatchEmail(raw);
    const ot = text.match(oldTrack)?.[1] ?? null;
    const nt = text.match(newTrack)?.[1] ?? null;
    const oc = text.match(oldCar)?.[1]?.trim() ?? null;
    const nc = text.match(newCar)?.[1]?.trim() ?? null;
    console.log("---", dir + "/" + f);
    console.log("parsed", JSON.stringify(parsed));
    console.log("track old/new", JSON.stringify(ot), JSON.stringify(nt), ot === nt ? "SAME" : "DIFF");
    console.log("carrier old/new", JSON.stringify(oc), JSON.stringify(nc), oc === nc ? "SAME" : "DIFF");
    const hitsT = [...text.matchAll(new RegExp(newTrack.source, "gi"))].map(m => m[1]);
    const hitsC = [...text.matchAll(new RegExp(newCar.source, "gi"))].map(m => m[1].trim());
    if (hitsT.length > 1) console.log("MULTI TRACK", hitsT);
    if (hitsC.length > 1) console.log("MULTI CARRIER", hitsC);
  }
}
'

